export function drawExampleSheet(canvas){
 canvas.width=1600;canvas.height=1900;const c=canvas.getContext('2d');
 c.fillStyle='#edf2f7';c.fillRect(0,0,1600,1900);c.fillStyle='#102d43';c.fillRect(0,0,1600,200);c.fillStyle='#58bbfa';c.font='700 19px "Malgun Gothic",sans-serif';c.fillText('SCROLL STUDIO · DIALOGUE COLLECTION',64,57);c.fillStyle='white';c.font='700 48px "Malgun Gothic",sans-serif';c.fillText('장면에 맞는 말풍선, 16가지',64,122);c.fillStyle='#c0d4e4';c.font='23px "Malgun Gothic",sans-serif';c.fillText('모양과 선으로 목소리를, 꼬리로 말하는 사람을 보여주세요.',64,166);
 balloonPresets.forEach((p,i)=>{const x=48+(i%4)*384,y=232+Math.floor(i/4)*388;c.fillStyle='white';c.beginPath();c.roundRect(x,y,368,366,14);c.fill();c.strokeStyle='#d5e1eb';c.lineWidth=1;c.stroke();c.save();c.translate(x,y);balloonDraw(c,{...presetStyle(p,4.5),font:p.style.font*2.1,x:.12,y:.13,w:.76,h:.62,text:p.text},368,260);c.restore();c.fillStyle='#238ed2';c.font='700 16px "Malgun Gothic",sans-serif';c.fillText(String(i+1).padStart(2,'0'),x+24,y+282);c.fillStyle='#182e40';c.font='700 23px "Malgun Gothic",sans-serif';c.fillText(p.label,x+57,y+283);c.fillStyle='#617485';c.font='15px "Malgun Gothic",sans-serif';c.fillText(p.hint,x+24,y+321,320);});
 c.fillStyle='#536c81';c.font='19px "Malgun Gothic",sans-serif';c.fillText('같은 목소리에는 같은 규칙을 · 꼬리는 짧게 · 얼굴과 꼬리를 겹치지 않게',64,1835);c.font='16px "Malgun Gothic",sans-serif';c.fillText('참고: oyasumi-gamedev.com/manga-speech-balloon-design/ · Blambot Comic Book Grammar & Tradition',64,1870);
}
